<?php
declare(strict_types=1);require __DIR__.'/../config/config.php';
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$u=current_user();
$action=$_GET['action']??'dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='add_medicine'){$s=db()->prepare('INSERT INTO medicines (name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['generic_name']??''),trim($_POST['strength']??''),trim($_POST['manufacturer']??''),trim($_POST['barcode']??'')?:null,trim($_POST['unit_name']??'tablet')?:'tablet',max(1,(int)($_POST['units_per_strip']??1)),max(1,(int)($_POST['strips_per_box']??1)),max(0,(float)($_POST['purchase_price']??0)),max(0,(float)($_POST['retail_unit_price']??0)),max(0,(int)($_POST['reorder_level']??0)),min(100,max(0,(float)($_POST['min_profit_margin_pct']??10)))]);audit_log('medicine_created','Medicine: '.trim($_POST['name']));header('Location: index.php?action=medicines&saved=1');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='sale'){$items=json_decode($_POST['items']??'[]',true)?:[];if(!$items)exit('Cart is empty.');$method=$_POST['payment_method']??'cash';$customerId=(int)($_POST['customer_id']??0);if($method==='credit'&&!$customerId)exit('Customer is required for a credit sale.');if($method!=='credit')$customerId=0;$pdo=db();$pdo->beginTransaction();try{$sub=0;foreach($items as $x){$sub+=(float)$x['price']*(int)$x['qty'];}$disc=max(0,(float)($_POST['discount']??0));$total=max(0,$sub-$disc);$paid=max(0,(float)($_POST['paid']??$total));if($paid>$total)throw new RuntimeException('Amount received cannot exceed sale total.');if($method!=='credit'&&$paid<$total)throw new RuntimeException('Amount received must cover the sale total.');$inv='INV-'.date('YmdHis').'-'.random_int(100,999);$pdo->prepare('INSERT INTO sales(invoice_no,customer_id,subtotal,discount,total,payment_method,paid) VALUES(?,?,?,?,?,?,?)')->execute([$inv,$customerId?:null,$sub,$disc,$total,$method,$paid]);$sid=(int)$pdo->lastInsertId();foreach($items as $x){$qty=max(1,(int)$x['qty']);$mid=(int)$x['id'];$b=$pdo->prepare('SELECT b.* FROM batches b WHERE b.medicine_id=? AND b.units_remaining>=? AND (b.expiry_date IS NULL OR b.expiry_date>=CURDATE()) ORDER BY b.expiry_date IS NULL,b.expiry_date,b.id FOR UPDATE');$b->execute([$mid,$qty]);$batch=$b->fetch();if(!$batch)throw new RuntimeException('Insufficient valid stock for '.($x['name']??'medicine'));$price=(float)$x['price']/$qty;$pdo->prepare('INSERT INTO sale_items(sale_id,medicine_id,batch_id,quantity_units,unit_price,line_total) VALUES(?,?,?,?,?,?)')->execute([$sid,$mid,$batch['id'],$qty,$price,$price*$qty]);$pdo->prepare('UPDATE batches SET units_remaining=units_remaining-? WHERE id=?')->execute([$qty,$batch['id']]);$pdo->prepare('INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?,"sale",?,?,?)')->execute([$mid,$batch['id'],-$qty,$sid,'POS sale']);}$pdo->commit();audit_log('sale_completed','Invoice '.$inv.' · Rs. '.number_format($total,2).' · Payment: '.$method.' · Discount: Rs. '.number_format($disc,2));header('Location: index.php?action=receipt&id='.$sid);exit;}catch(Throwable $e){$pdo->rollBack();http_response_code(400);exit('Sale failed: '.h($e->getMessage()));}}
if($action==='pos'){header('Location: pos.php');exit;}if($action==='inventory'){header('Location: inventory.php');exit;}if($action==='reports'){header('Location: manage.php?tab=reports');exit;}
